"""Build the static site with the owner's explicitly chosen public support email."""
from pathlib import Path
from html import escape
import argparse
p = argparse.ArgumentParser()
p.add_argument('--email', required=True)
a = p.parse_args()
assert '@' in a.email and '\n' not in a.email
email = escape(a.email, quote=True)
root = Path(__file__).parent

def page(name, title, description, body):
    html = f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="{escape(description,quote=True)}"><meta name="color-scheme" content="light"><title>{title} | RunConvert</title><link rel="icon" href="/assets/icon.png"><link rel="stylesheet" href="/styles.css"></head><body><header><a class="brand" href="/"><img src="/assets/icon.png" alt="" width="44" height="44">RunConvert</a><nav aria-label="Main navigation"><a href="/support">Support</a><a href="/privacy">Privacy</a></nav></header>{body}<footer><span>RunConvert · Made by aisolo</span><span>Free. Offline. No account.</span></footer></body></html>'''
    (root / name).write_text(html)

page('index.html', 'Running conversions, without the extra math', 'A free offline iPhone app for running pace, distance, finish times, and workout conversions.', '''<main><section class="hero"><span class="eyebrow">A simple tool for runners</span><h1>Your run.<br>Both sets of units.</h1><p class="lead">Convert pace, distance, finish times, and workouts right on your iPhone. Just enter your numbers and get back to your run.</p><div class="pills"><span class="pill">Free</span><span class="pill">Works offline</span><span class="pill">No ads or tracking</span></div></section><section class="grid" aria-label="What RunConvert does"><article class="card"><span class="number">01 / PACE</span><h2>Min/km to min/mi.</h2><p>Convert a single pace or a whole pace range in either direction.</p><p class="example">5:00/km → 8:03/mi</p></article><article class="card"><span class="number">02 / DISTANCE</span><h2>Kilometers to miles.</h2><p>Use decimals or a distance range. Switch units with a tap.</p><p class="example">10 km → 6.21 mi</p></article><article class="card"><span class="number">03 / TIME</span><h2>Work out your finish time.</h2><p>Estimate a finish time from your pace, or find the pace for a target time.</p><p class="example">10 km at 5:00/km → 50:00</p></article><article class="card"><span class="number">04 / WORKOUT</span><h2>Convert the whole workout.</h2><p>Build a normal run or interval session with warm-up, work, recovery, repeat blocks, and cool-down.</p></article></section><div class="note"><h2>Your inputs stay on your phone.</h2><p>No account, saved workout history, analytics, or advertising SDKs. RunConvert does the math on your device.</p><a href="/privacy">Read the privacy policy</a></div><p>For iPhone with iOS 17 or later. App Store release is being prepared.</p></main>''')
page('support.html', 'Support', 'Help with RunConvert pace, distance, time, and workout conversions.', f'''<main class="legal"><span class="eyebrow">RunConvert help</span><h1>Need a hand?</h1><p class="lead">If a conversion looks wrong or something isn't working, send me what you entered and what happened.</p><p><a class="button" href="mailto:{email}?subject=RunConvert%20support">Email support</a></p><p><a href="mailto:{email}">{email}</a></p><section><h2>Pace and distance</h2><p>For pace, type 500 for 5:00. Tap the unit button to switch between min/km and min/mi. Distance fields accept decimals. Choose the range option to convert two values.</p></section><section><h2>Time and target pace</h2><p>In Time, enter a distance and pace, then tap Estimate. To work backward from a finish time, use Target Pace and tap Find Pace.</p></section><section><h2>Workouts</h2><p>Choose Normal Run or Intervals in the Workout tab. For intervals, add your warm-up, work and recovery steps, repeat blocks, and cool-down, then tap Convert to see the summary.</p></section><section><h2>Before you email</h2><p>Include your iPhone model, iOS version, the tab you were using, and the numbers you entered. A screenshot can help. Please leave out sensitive information.</p><p>Inputs are temporary. RunConvert does not save a workout history. Clear resets the current converter; closing the app may discard your entries.</p></section><section><h2>Privacy</h2><p>Conversions work offline. Emailing support or opening this website uses your email or browser service separately. <a href="/privacy">Read the privacy policy</a>.</p></section></main>''')
page('privacy.html', 'Privacy policy', 'RunConvert does not collect data or track you. Calculations stay on your iPhone.', f'''<main class="legal"><span class="eyebrow">RunConvert</span><h1>Privacy policy</h1><p class="updated">Updated September 27, 2026</p><p class="lead">RunConvert works offline. Your pace, distance, time, and workout values are processed on your device. The app does not send those values to me or anyone else.</p><section><h2>Data in the app</h2><p>RunConvert does not collect personal data, track you, use analytics or advertising SDKs, or require an account. It does not access Apple Health, location, contacts, photos, or your microphone.</p><p>Inputs are held in memory while the app is running. The app does not save a workout history or upload your entries. Clear resets the current converter. There is no server-side account or stored workout data to delete.</p></section><section><h2>Apple services</h2><p>Apple may separately process download, App Store, or diagnostic information under its own settings and <a href="https://www.apple.com/legal/privacy/">privacy policy</a>.</p></section><section><h2>If you contact me</h2><p>If you email support, I receive your email address and the information you choose to send so I can respond. Your message is handled by the email services involved and may remain in the support mailbox. You can email me to request deletion of a support conversation. Please don't send sensitive information or personal workout details you don't want to share.</p></section><section><h2>This website</h2><p>This site is hosted on Vercel. Vercel may process technical request information, including IP addresses, browser information, and request logs, to deliver and secure the site. This website does not add analytics, advertising scripts, or tracking cookies. Website requests are separate from the offline app's conversions.</p><p>See <a href="https://vercel.com/legal/privacy-notice">Vercel's privacy notice</a> for its practices.</p></section><section><h2>Changes and contact</h2><p>If the app's privacy practices change, I'll update this policy and its date. For privacy questions or support, contact <a href="mailto:{email}">{email}</a>.</p><p>RunConvert is made by aisolo.</p></section></main>''')
print('Built index.html, support.html, privacy.html')
